func newDealsCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "deals",
		Short: "Scan an Affiliate category feed for products above a discount threshold.",
		RunE:  parentNoSubcommandRunE(flags),
	}
	cmd.AddCommand(newDealsCategoryCmd(flags))
	return cmd
}

func newDealsCategoryCmd(flags *rootFlags) *cobra.Command {
	var flagMinDiscount float64
	var flagTrackingID string

	cmd := &cobra.Command{
		Use:   "category <category> [--min-discount <n>]",
		Short: "Scan an entire Affiliate category feed for products at or above a discount threshold.",
		Long: `Calls the official Affiliate Category Feed API, filters to products whose
discountPercentage is at or above --min-discount, and stores matches in the
local generic resources table (resource type "products") so they stay
queryable afterward via 'analytics --type products'.

Requires FLIPKART_AFFILIATE_ID and FLIPKART_AFFILIATE_TOKEN (or pass
--tracking-id to override the tracking ID).`,
		Example:     `  flipkart-pp-cli deals category mobiles --min-discount 30`,
		Annotations: map[string]string{"pp:endpoint": "deals.category", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			category := args[0]

			// dry-run must short-circuit before any required-flag or
			// credential validation so `--dry-run` always succeeds
			// (per the Verify-friendly RunE convention) regardless of
			// whether --min-discount or affiliate credentials are set.
			if dryRunOK(flags) {
				minDiscountMsg := "(not set)"
				if cmd.Flags().Changed("min-discount") {
					minDiscountMsg = fmt.Sprintf("%v", flagMinDiscount)
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "would fetch category feed %q and keep products with discountPercentage >= %s\n(dry run - no request sent)\n", category, minDiscountMsg)
				return nil
			}

			if !cmd.Flags().Changed("min-discount") {
				return usageErr(fmt.Errorf("--min-discount is required\nUsage: %s <category> [--min-discount <n>]", cmd.CommandPath()))
			}

			trackingID := flagTrackingID
			if trackingID == "" {
				trackingID = os.Getenv("FLIPKART_AFFILIATE_ID")
			}
			if trackingID == "" || os.Getenv("FLIPKART_AFFILIATE_TOKEN") == "" {
				return authErr(fmt.Errorf("deals category requires both FLIPKART_AFFILIATE_ID and FLIPKART_AFFILIATE_TOKEN to be set (or pass --tracking-id for the ID)"))
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c = c.WithTier("affiliate")

			path := "/1.0/feeds/{tracking_id}/category/{category}.json"
			path = replacePathParam(path, "tracking_id", trackingID)
			path = replacePathParam(path, "category", category)

			data, _, err := resolveRead(cmd.Context(), c, flags, "feed", false, path, map[string]string{}, nil)
			if err != nil {
				return classifyAPIError(err, flags)
			}

			nodes := extractDiscountedNodes(data)
			var matched []feedDigestItem
			for _, n := range nodes {
				if n.DiscountPercentage >= flagMinDiscount {
					matched = append(matched, n)
				}
			}
			sort.SliceStable(matched, func(i, j int) bool {
				return math.Abs(matched[i].DiscountPercentage) > math.Abs(matched[j].DiscountPercentage)
			})

			if cliutil.IsDogfoodEnv() && len(matched) > 1 {
				matched = matched[:1]
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()

			stored := 0
			if len(matched) > 0 {
				items := make([]json.RawMessage, 0, len(matched))
				for _, m := range matched {
					if m.Raw != nil {
						items = append(items, m.Raw)
					}
				}
				if len(items) > 0 {
					stored, _, err = db.UpsertBatch("products", items)
					if err != nil {
						return fmt.Errorf("persisting matched deals: %w", err)
					}
				}
			}

			return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
				"category":         category,
				"min_discount":     flagMinDiscount,
				"matched_count":    len(matched),
				"stored_count":     stored,
				"matched_products": matched,
			}, flags)
		},
	}
	cmd.Flags().Float64Var(&flagMinDiscount, "min-discount", 0, "Minimum discount percentage to keep (required)")
	cmd.Flags().StringVar(&flagTrackingID, "tracking-id", "", "Affiliate tracking ID override (defaults to FLIPKART_AFFILIATE_ID)")
	return cmd
}
